  @protected
  void sse_encode_player_event(PlayerEvent self, SseSerializer serializer) {
    // Codec=Sse (Serialization based), see doc to use other codecs
    switch (self) {
      case PlayerEvent_Loaded(track: final track, index: final index):
        sse_encode_i_32(0, serializer);
        sse_encode_box_autoadd_track_info(track, serializer);
        sse_encode_u_32(index, serializer);
      case PlayerEvent_Path(path: final path):
        sse_encode_i_32(1, serializer);
        sse_encode_box_autoadd_signal_path(path, serializer);
      case PlayerEvent_Playing(playing: final playing):
        sse_encode_i_32(2, serializer);
        sse_encode_bool(playing, serializer);
      case PlayerEvent_Position(secs: final secs):
        sse_encode_i_32(3, serializer);
        sse_encode_f_64(secs, serializer);
      case PlayerEvent_Ended():
        sse_encode_i_32(4, serializer);
      case PlayerEvent_Error(message: final message, index: final index):
        sse_encode_i_32(5, serializer);
        sse_encode_String(message, serializer);
        sse_encode_u_32(index, serializer);
    }
  }

